    {visible.length > 0 && renderTokens(visible)}
    {small.length > 0 && <details className="small-wallet-tokens"><summary title="Based on unrounded USD values. These tokens remain included in wallet value and income totals.">Tokens below $0.01 ({small.length})</summary>{renderTokens(small)}</details>}
